from typing import Dict, List, Any

# Canonical definitions of realistic multi-speaker earnings calls (Operator, CEO, CFO, Analysts)
COMPANY_SPEECH_DATA: Dict[str, Dict[str, Any]] = {'AAPL': {'text': "Good day and welcome to the Apple Q3 FY2026 earnings conference call. At this time, I would like to turn the call over to Suhasini Chandramouli, Director of Investor Relations. Speaking first today is Apple's CEO, Tim Cook, and he will be followed by CFO, Luca Maestri. Today, Apple is reporting a new June quarter revenue record of 85.8 billion, up 5 percent from a year ago. Services set an all-time revenue record of 24.2 billion, up 14 percent year-over-year. Gross margin was 46.3 percent, near the high end of our guidance. Diluted EPS was 1.40. We returned over 32 billion to shareholders through dividends and share repurchases. We will now begin the question-and-answer session. Our first question comes from Shannon Cross with AllianceBernstein. Thank you. Tim, could you expand on customer reception to Apple Intelligence across Greater China and Europe? We are seeing very strong enthusiasm from developers and consumers alike. The integration of generative AI into iOS 18 is driving accelerated upgrade cycles. Our next question comes from Toni Sacconaghi with Bernstein. Luca, how should we think about gross margin trajectory and Services mix heading into the September quarter? We expect gross margins between 46.0 percent and 47.0 percent, benefiting from favorable Services mix and ongoing cost efficiencies. Our next question comes from Amit Daryanani with Evercore ISI. Tim, are you seeing higher subscriber retention and engagement across iCloud and Apple Pay? Yes, Amit. Paid subscriptions grew double digits, surpassing 1 billion active paid subscriptions across our platform.", 'utterances': [{'speaker_id': 'S0', 'text': 'Good day and welcome to the Apple Q3 FY2026 earnings conference call. At this time, I would like to turn the call over to Suhasini Chandramouli, Director of Investor Relations.'}, {'speaker_id': 'S0', 'text': "Speaking first today is Apple's CEO, Tim Cook, and he will be followed by CFO, Luca Maestri."}, {'speaker_id': 'S1', 'text': 'Today, Apple is reporting a new June quarter revenue record of $85.8 billion, up 5% from a year ago. Services set an all-time revenue record of $24.2 billion, up 14% year-over-year.'}, {'speaker_id': 'S2', 'text': 'Gross margin was 46.3%, near the high end of our guidance. Diluted EPS was $1.40. We returned over $32 billion to shareholders through dividends and share repurchases.'}, {'speaker_id': 'S0', 'text': 'We will now begin the question-and-answer session. Our first question comes from Shannon Cross with AllianceBernstein.'}, {'speaker_id': 'S3', 'text': 'Thank you. Tim, could you expand on customer reception to Apple Intelligence across Greater China and Europe?'}, {'speaker_id': 'S1', 'text': 'We are seeing very strong enthusiasm from developers and consumers alike. The integration of generative AI into iOS 18 is driving accelerated upgrade cycles.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Toni Sacconaghi with Bernstein.'}, {'speaker_id': 'S4', 'text': 'Luca, how should we think about gross margin trajectory and Services mix heading into the September quarter?'}, {'speaker_id': 'S2', 'text': 'We expect gross margins between 46.0% and 47.0%, benefiting from favorable Services mix and ongoing cost efficiencies.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Amit Daryanani with Evercore ISI.'}, {'speaker_id': 'S5', 'text': 'Tim, are you seeing higher subscriber retention and engagement across iCloud and Apple Pay?'}, {'speaker_id': 'S1', 'text': 'Yes, Amit. Paid subscriptions grew double digits, surpassing 1 billion active paid subscriptions across our platform.'}]}, 'MSFT': {'text': 'Welcome to the Microsoft Fiscal Year 2026 Fourth Quarter Earnings Conference Call. I will now turn the call over to Brett Iversen, Vice President of Investor Relations. On the call with me today are Satya Nadella, Chief Executive Officer, and Amy Hood, Chief Financial Officer. We closed out our fiscal year with strong results. Microsoft Cloud revenue surpassed 36.8 billion, up 21 percent year-over-year. Total company revenue was 64.7 billion, up 15 percent. Operating income increased 15 percent to 27.9 billion. We will now take your questions. Our first question comes from Keith Weiss with Morgan Stanley. Satya, could you speak to the scaling of Azure AI and customer capacity constraints? We are seeing accelerating demand across Copilot and Azure OpenAI services, with enterprise adoption expanding globally. Our next question comes from Brent Thill with Jefferies. Amy, what is your expectation for capital expenditures in fiscal 2027 to support AI infrastructure? We will continue to invest in cloud capacity, aligning CapEx with long-term revenue growth opportunities. Our next question comes from Karl Keirstead with UBS. Satya, how are enterprise customers approaching commercial Office 365 Copilot monetization? Customers are realizing measurable productivity gains, driving higher seat expansion and renewal rates.', 'utterances': [{'speaker_id': 'S0', 'text': 'Welcome to the Microsoft Fiscal Year 2026 Fourth Quarter Earnings Conference Call. I will now turn the call over to Brett Iversen, Vice President of Investor Relations.'}, {'speaker_id': 'S0', 'text': 'On the call with me today are Satya Nadella, Chief Executive Officer, and Amy Hood, Chief Financial Officer.'}, {'speaker_id': 'S1', 'text': 'We closed out our fiscal year with strong results. Microsoft Cloud revenue surpassed $36.8 billion, up 21% year-over-year.'}, {'speaker_id': 'S2', 'text': 'Total company revenue was $64.7 billion, up 15%. Operating income increased 15% to $27.9 billion.'}, {'speaker_id': 'S0', 'text': 'We will now take your questions. Our first question comes from Keith Weiss with Morgan Stanley.'}, {'speaker_id': 'S3', 'text': 'Satya, could you speak to the scaling of Azure AI and customer capacity constraints?'}, {'speaker_id': 'S1', 'text': 'We are seeing accelerating demand across Copilot and Azure OpenAI services, with enterprise adoption expanding globally.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Brent Thill with Jefferies.'}, {'speaker_id': 'S4', 'text': 'Amy, what is your expectation for capital expenditures in fiscal 2027 to support AI infrastructure?'}, {'speaker_id': 'S2', 'text': 'We will continue to invest in cloud capacity, aligning CapEx with long-term revenue growth opportunities.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Karl Keirstead with UBS.'}, {'speaker_id': 'S5', 'text': 'Satya, how are enterprise customers approaching commercial Office 365 Copilot monetization?'}, {'speaker_id': 'S1', 'text': 'Customers are realizing measurable productivity gains, driving higher seat expansion and renewal rates.'}]}, 'GOOGL': {'text': "Good afternoon and welcome to Alphabet's quarterly earnings conference call. With us today are Sundar Pichai, CEO, and Anat Ashkenazi, Chief Financial Officer. Our consolidated revenues were 84.7 billion, an increase of 14 percent year-over-year. Google Cloud revenue grew 29 percent to 10.3 billion. Operating margin expanded to 32 percent, reflecting disciplined operational execution alongside AI infrastructure investments. We will now open the floor for analyst questions. First question comes from Brian Nowak with Morgan Stanley. Sundar, how is AI Overviews in Search impacting user search frequency and query monetization? AI Overviews are driving positive query volume growth and higher user satisfaction across mobile and desktop. Our next question comes from Doug Anmuth with JPMorgan. Anat, can you provide an update on technical infrastructure efficiency and margin improvement? We remain disciplined on our cost structure while maintaining strong investment in compute infrastructure. Our next question comes from Ross Sandler with Barclays. Sundar, how is YouTube advertising demand evolving across Connected TV and Shorts? YouTube continues to demonstrate strong engagement, particularly in Connected TV living room viewing.", 'utterances': [{'speaker_id': 'S0', 'text': "Good afternoon and welcome to Alphabet's quarterly earnings conference call. With us today are Sundar Pichai, CEO, and Anat Ashkenazi, Chief Financial Officer."}, {'speaker_id': 'S1', 'text': 'Our consolidated revenues were $84.7 billion, an increase of 14% year-over-year. Google Cloud revenue grew 29% to $10.3 billion.'}, {'speaker_id': 'S2', 'text': 'Operating margin expanded to 32%, reflecting disciplined operational execution alongside AI infrastructure investments.'}, {'speaker_id': 'S0', 'text': 'We will now open the floor for analyst questions. First question comes from Brian Nowak with Morgan Stanley.'}, {'speaker_id': 'S3', 'text': 'Sundar, how is AI Overviews in Search impacting user search frequency and query monetization?'}, {'speaker_id': 'S1', 'text': 'AI Overviews are driving positive query volume growth and higher user satisfaction across mobile and desktop.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Doug Anmuth with JPMorgan.'}, {'speaker_id': 'S4', 'text': 'Anat, can you provide an update on technical infrastructure efficiency and margin improvement?'}, {'speaker_id': 'S2', 'text': 'We remain disciplined on our cost structure while maintaining strong investment in compute infrastructure.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Ross Sandler with Barclays.'}, {'speaker_id': 'S5', 'text': 'Sundar, how is YouTube advertising demand evolving across Connected TV and Shorts?'}, {'speaker_id': 'S1', 'text': 'YouTube continues to demonstrate strong engagement, particularly in Connected TV living room viewing.'}]}, 'TSLA': {'text': 'Good day and welcome to the Tesla Q3 earnings conference call. Joining us today are Elon Musk, Chief Executive Officer, and Vaibhav Taneja, Chief Financial Officer. In the quarter, we achieved total revenue of 25.1 billion, up 8 percent year-over-year. Our energy storage business had record deployment of 6.9 gigawatt hours. Free cash flow reached 2.74 billion, supporting our ongoing expansion of AI compute clusters and vehicle manufacturing lines. We will now begin the question and answer session. Our first question comes from Adam Jonas with Morgan Stanley. Elon, what is the roadmap for autonomous Cybercab production and Full Self-Driving deployment? We are on track to begin volume production in 2026 with unmatched cost per passenger mile. Our next question comes from Dan Levy with Barclays. Vaibhav, how should we model automotive gross margin excluding regulatory credits into next year? Cost reductions in raw materials and manufacturing efficiency continue to improve unit margins. Our next question comes from Pierre Ferragu with New Street Research. Elon, how is Megapack demand scaling relative to manufacturing capacity in Lathrop and Shanghai? Energy storage demand remains exceptionally robust, outpacing our automotive growth rate.', 'utterances': [{'speaker_id': 'S0', 'text': 'Good day and welcome to the Tesla Q3 earnings conference call. Joining us today are Elon Musk, Chief Executive Officer, and Vaibhav Taneja, Chief Financial Officer.'}, {'speaker_id': 'S1', 'text': 'In the quarter, we achieved total revenue of $25.1 billion, up 8% year-over-year. Our energy storage business had record deployment of 6.9 gigawatt hours.'}, {'speaker_id': 'S2', 'text': 'Free cash flow reached $2.74 billion, supporting our ongoing expansion of AI compute clusters and vehicle manufacturing lines.'}, {'speaker_id': 'S0', 'text': 'We will now begin the question and answer session. Our first question comes from Adam Jonas with Morgan Stanley.'}, {'speaker_id': 'S3', 'text': 'Elon, what is the roadmap for autonomous Cybercab production and Full Self-Driving deployment?'}, {'speaker_id': 'S1', 'text': 'We are on track to begin volume production in 2026 with unmatched cost per passenger mile.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Dan Levy with Barclays.'}, {'speaker_id': 'S4', 'text': 'Vaibhav, how should we model automotive gross margin excluding regulatory credits into next year?'}, {'speaker_id': 'S2', 'text': 'Cost reductions in raw materials and manufacturing efficiency continue to improve unit margins.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Pierre Ferragu with New Street Research.'}, {'speaker_id': 'S5', 'text': 'Elon, how is Megapack demand scaling relative to manufacturing capacity in Lathrop and Shanghai?'}, {'speaker_id': 'S1', 'text': 'Energy storage demand remains exceptionally robust, outpacing our automotive growth rate.'}]}, 'JPM': {'text': "Good morning and welcome to JPMorgan Chase's quarterly earnings conference call. Today's call is hosted by Chairman and CEO Jamie Dimon and CFO Jeremy Barnum. The firm reported strong results with net income of 18.1 billion on revenue of 50.99 billion, driven by balanced growth across our lines of business. Net interest income was 22.9 billion, while our Common Equity Tier 1 capital ratio remained exceptionally robust at 15.3 percent. We will now take questions from the analyst community. First question comes from Betsy Graseck with Morgan Stanley. Jamie, what are your latest views on macroeconomic resilience and net interest income trajectory? The US economy continues to be resilient, though geopolitical risks and inflation require prudent risk management. Our next question comes from Ebrahim Poonawala with Bank of America. Jeremy, how are investment banking fees and advisory pipelines shaping up for the second half? We are seeing encouraging activity in debt underwriting and mergers and acquisitions. Our next question comes from Mike Mayo with Wells Fargo. Jamie, how is artificial intelligence impacting operating efficiency across commercial banking? We have thousands of people working on AI use cases that enhance underwriting accuracy and reduce fraud.", 'utterances': [{'speaker_id': 'S0', 'text': "Good morning and welcome to JPMorgan Chase's quarterly earnings conference call. Today's call is hosted by Chairman and CEO Jamie Dimon and CFO Jeremy Barnum."}, {'speaker_id': 'S1', 'text': 'The firm reported strong results with net income of $18.1 billion on revenue of $50.99 billion, driven by balanced growth across our lines of business.'}, {'speaker_id': 'S2', 'text': 'Net interest income was $22.9 billion, while our Common Equity Tier 1 capital ratio remained exceptionally robust at 15.3%.'}, {'speaker_id': 'S0', 'text': 'We will now take questions from the analyst community. First question comes from Betsy Graseck with Morgan Stanley.'}, {'speaker_id': 'S3', 'text': 'Jamie, what are your latest views on macroeconomic resilience and net interest income trajectory?'}, {'speaker_id': 'S1', 'text': 'The US economy continues to be resilient, though geopolitical risks and inflation require prudent risk management.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Ebrahim Poonawala with Bank of America.'}, {'speaker_id': 'S4', 'text': 'Jeremy, how are investment banking fees and advisory pipelines shaping up for the second half?'}, {'speaker_id': 'S2', 'text': 'We are seeing encouraging activity in debt underwriting and mergers and acquisitions.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Mike Mayo with Wells Fargo.'}, {'speaker_id': 'S5', 'text': 'Jamie, how is artificial intelligence impacting operating efficiency across commercial banking?'}, {'speaker_id': 'S1', 'text': 'We have thousands of people working on AI use cases that enhance underwriting accuracy and reduce fraud.'}]}, 'XOM': {'text': 'Welcome to the ExxonMobil second-quarter earnings call. Speaking today are Chairman and CEO Darren Woods and CFO Kathryn Mikells. Today, ExxonMobil reported solid second-quarter earnings of 9.2 billion, driven by advantaged growth in Guyana and the Permian Basin. Cash flow from operations was 10.6 billion, enabling 4.3 billion in dividend distributions and 5.2 billion in share repurchases. We will now begin the question-and-answer session. Our first question comes from Neil Mehta with Goldman Sachs. Darren, could you discuss Pioneer Natural Resources integration synergies and production volume targets? The integration is progressing ahead of plan, allowing us to capture higher recovery rates across our Permian acreage. Our next question comes from Devin McDermott with Morgan Stanley. Kathryn, how should we think about cash distribution pace via dividends and buybacks? Our strong balance sheet allows us to maintain competitive dividend growth while repurchasing shares. Our next question comes from Biraj Borkhataria with RBC Capital Markets. Darren, what is the latest status on Low Carbon Solutions commercial contracts? We are seeing growing customer interest in carbon capture and storage agreements across the US Gulf Coast.', 'utterances': [{'speaker_id': 'S0', 'text': 'Welcome to the ExxonMobil second-quarter earnings call. Speaking today are Chairman and CEO Darren Woods and CFO Kathryn Mikells.'}, {'speaker_id': 'S1', 'text': 'Today, ExxonMobil reported solid second-quarter earnings of $9.2 billion, driven by advantaged growth in Guyana and the Permian Basin.'}, {'speaker_id': 'S2', 'text': 'Cash flow from operations was $10.6 billion, enabling $4.3 billion in dividend distributions and $5.2 billion in share repurchases.'}, {'speaker_id': 'S0', 'text': 'We will now begin the question-and-answer session. Our first question comes from Neil Mehta with Goldman Sachs.'}, {'speaker_id': 'S3', 'text': 'Darren, could you discuss Pioneer Natural Resources integration synergies and production volume targets?'}, {'speaker_id': 'S1', 'text': 'The integration is progressing ahead of plan, allowing us to capture higher recovery rates across our Permian acreage.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Devin McDermott with Morgan Stanley.'}, {'speaker_id': 'S4', 'text': 'Kathryn, how should we think about cash distribution pace via dividends and buybacks?'}, {'speaker_id': 'S2', 'text': 'Our strong balance sheet allows us to maintain competitive dividend growth while repurchasing shares.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Biraj Borkhataria with RBC Capital Markets.'}, {'speaker_id': 'S5', 'text': 'Darren, what is the latest status on Low Carbon Solutions commercial contracts?'}, {'speaker_id': 'S1', 'text': 'We are seeing growing customer interest in carbon capture and storage agreements across the US Gulf Coast.'}]}, 'LMB': {'text': 'Good morning and welcome to Limbach Holdings earnings conference call. Speaking today is CEO Mike McCann and CFO Jay Sharp. We are pleased to announce quarterly revenue of 135.2 million, expanding our gross margin to 24.5 percent. Owner-direct revenue reached 62 percent of total revenue, generating free cash flow of 14.1 million. We will now open the line for analyst questions. First question comes from Rob Brown with Lake Street Capital Markets. Mike, could you provide more detail on owner-direct revenue growth and customer retention? Owner-direct relationships expanded to 62 percent of total revenue, driving higher gross margins. Our next question comes from Gerry Sweeney with ROTH MKM. How does the acquisition pipeline look for expanding specialized mechanical services? We continue to evaluate accretive tuck-in acquisitions that enhance our recurring maintenance profile. Our next question comes from Brent Thielman with D.A. Davidson. What is your outlook for data center and industrial project demand? Demand from mission-critical facilities remains very healthy across our primary geographies.', 'utterances': [{'speaker_id': 'S0', 'text': 'Good morning and welcome to Limbach Holdings earnings conference call. Speaking today is CEO Mike McCann and CFO Jay Sharp.'}, {'speaker_id': 'S1', 'text': 'We are pleased to announce quarterly revenue of $135.2 million, expanding our gross margin to 24.5%.'}, {'speaker_id': 'S2', 'text': 'Owner-direct revenue reached 62% of total revenue, generating free cash flow of $14.1 million.'}, {'speaker_id': 'S0', 'text': 'We will now open the line for analyst questions. First question comes from Rob Brown with Lake Street Capital Markets.'}, {'speaker_id': 'S3', 'text': 'Mike, could you provide more detail on owner-direct revenue growth and customer retention?'}, {'speaker_id': 'S1', 'text': 'Owner-direct relationships expanded to 62% of total revenue, driving higher gross margins.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Gerry Sweeney with ROTH MKM.'}, {'speaker_id': 'S4', 'text': 'How does the acquisition pipeline look for expanding specialized mechanical services?'}, {'speaker_id': 'S1', 'text': 'We continue to evaluate accretive tuck-in acquisitions that enhance our recurring maintenance profile.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Brent Thielman with D.A. Davidson.'}, {'speaker_id': 'S5', 'text': 'What is your outlook for data center and industrial project demand?'}, {'speaker_id': 'S1', 'text': 'Demand from mission-critical facilities remains very healthy across our primary geographies.'}]}, 'APT': {'text': "Good day and welcome to Alpha Pro Tech's earnings conference call. Speaking today are CEO Lloyd Hoffman and CFO Colleen McDonald. Total consolidated sales for the quarter were 16.4 million, with gross profit margin of 37.8 percent. Cash and cash equivalents grew to 18.2 million with zero long-term debt. We will now begin the question-and-answer session. First question comes from Kevin Smith with Equity Research. Lloyd, can you talk about order trends in building supply synthetic roof underlayment? Building supply revenue increased 12 percent due to residential re-roofing demand. Our next question comes from David Johnson with MicroCap Advisors. Colleen, how are input raw material costs and freight expenses trending? Freight costs have stabilized, allowing us to maintain healthy operating cash flow. Our next question comes from Sarah Miller with Value Investors. Lloyd, what is the strategy for disposable protective apparel in medical channels? We are focusing on high-margin cleanroom and pharmaceutical manufacturing customers.", 'utterances': [{'speaker_id': 'S0', 'text': "Good day and welcome to Alpha Pro Tech's earnings conference call. Speaking today are CEO Lloyd Hoffman and CFO Colleen McDonald."}, {'speaker_id': 'S1', 'text': 'Total consolidated sales for the quarter were $16.4 million, with gross profit margin of 37.8%.'}, {'speaker_id': 'S2', 'text': 'Cash and cash equivalents grew to $18.2 million with zero long-term debt.'}, {'speaker_id': 'S0', 'text': 'We will now begin the question-and-answer session. First question comes from Kevin Smith with Equity Research.'}, {'speaker_id': 'S3', 'text': 'Lloyd, can you talk about order trends in building supply synthetic roof underlayment?'}, {'speaker_id': 'S1', 'text': 'Building supply revenue increased 12% due to residential re-roofing demand.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from David Johnson with MicroCap Advisors.'}, {'speaker_id': 'S4', 'text': 'Colleen, how are input raw material costs and freight expenses trending?'}, {'speaker_id': 'S2', 'text': 'Freight costs have stabilized, allowing us to maintain healthy operating cash flow.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Sarah Miller with Value Investors.'}, {'speaker_id': 'S5', 'text': 'Lloyd, what is the strategy for disposable protective apparel in medical channels?'}, {'speaker_id': 'S1', 'text': 'We are focusing on high-margin cleanroom and pharmaceutical manufacturing customers.'}]}, 'DMRC': {'text': "Welcome to Digimarc's quarterly earnings conference call. Speaking today are CEO Riley McCormack and CFO Charles Beck. Total revenue for the quarter was 9.8 million, driven by 18 percent growth in commercial subscription revenue. Operating cash burn decreased 24 percent year-over-year as subscription annual recurring revenue expanded. We will now take questions. Our first question comes from George Sutton with Craig-Hallum. Riley, could you update us on Digimarc Validate adoption with European retail consortiums? We are seeing strong momentum as retailers seek product authentication to reduce counterfeit goods. Our next question comes from Matthew Galinko with Maxim Group. Charles, what is your guidance for cash burn reduction and path to profitability? Annualized operating expenses decreased 15 percent, extending our cash runway significantly. Our next question comes from James Mitchell with Tech Growth Research. Riley, how are industrial packaging converters integrating digital watermark technology? Top global packaging converters are embedding our digital identifiers directly on manufacturing lines.", 'utterances': [{'speaker_id': 'S0', 'text': "Welcome to Digimarc's quarterly earnings conference call. Speaking today are CEO Riley McCormack and CFO Charles Beck."}, {'speaker_id': 'S1', 'text': 'Total revenue for the quarter was $9.8 million, driven by 18% growth in commercial subscription revenue.'}, {'speaker_id': 'S2', 'text': 'Operating cash burn decreased 24% year-over-year as subscription annual recurring revenue expanded.'}, {'speaker_id': 'S0', 'text': 'We will now take questions. Our first question comes from George Sutton with Craig-Hallum.'}, {'speaker_id': 'S3', 'text': 'Riley, could you update us on Digimarc Validate adoption with European retail consortiums?'}, {'speaker_id': 'S1', 'text': 'We are seeing strong momentum as retailers seek product authentication to reduce counterfeit goods.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Matthew Galinko with Maxim Group.'}, {'speaker_id': 'S4', 'text': 'Charles, what is your guidance for cash burn reduction and path to profitability?'}, {'speaker_id': 'S2', 'text': 'Annualized operating expenses decreased 15%, extending our cash runway significantly.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from James Mitchell with Tech Growth Research.'}, {'speaker_id': 'S5', 'text': 'Riley, how are industrial packaging converters integrating digital watermark technology?'}, {'speaker_id': 'S1', 'text': 'Top global packaging converters are embedding our digital identifiers directly on manufacturing lines.'}]}, 'SHOP': {'text': "Good morning and welcome to Shopify's earnings conference call. Joining us are Harley Finkelstein, President, and Jeff Hoffmeister, CFO. Revenue for the quarter reached 2.05 billion, growing 21 percent year-over-year. Free cash flow margin was 16 percent. Gross Merchandise Volume expanded to 67.2 billion, up 22 percent, driven by merchant additions and same-store sales growth. Operator, please open the lines for questions. Our first question comes from Ken Wong with Oppenheimer. Harley, can you discuss enterprise merchant adoption and Shopify Plus momentum? Enterprise brands are migrating to Shopify at an unprecedented rate, leveraging our commerce operating system. Our next question comes from Paul Treiber with RBC Capital Markets. Jeff, how should we think about international expansion and merchant solution attach rates? International GMV grew 30 percent as cross-border tools like Shopify Markets gain adoption. Our next question comes from Colin Sebastian with Baird. Harley, how are merchants utilizing Shopify Magic and AI sidekick tools? Merchants using AI tools are saving hours each week on catalog generation and customer support.", 'utterances': [{'speaker_id': 'S0', 'text': "Good morning and welcome to Shopify's earnings conference call. Joining us are Harley Finkelstein, President, and Jeff Hoffmeister, CFO."}, {'speaker_id': 'S1', 'text': 'Revenue for the quarter reached $2.05 billion, growing 21% year-over-year. Free cash flow margin was 16%.'}, {'speaker_id': 'S2', 'text': 'Gross Merchandise Volume expanded to $67.2 billion, up 22%, driven by merchant additions and same-store sales growth.'}, {'speaker_id': 'S0', 'text': 'Operator, please open the lines for questions. Our first question comes from Ken Wong with Oppenheimer.'}, {'speaker_id': 'S3', 'text': 'Harley, can you discuss enterprise merchant adoption and Shopify Plus momentum?'}, {'speaker_id': 'S1', 'text': 'Enterprise brands are migrating to Shopify at an unprecedented rate, leveraging our commerce operating system.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Paul Treiber with RBC Capital Markets.'}, {'speaker_id': 'S4', 'text': 'Jeff, how should we think about international expansion and merchant solution attach rates?'}, {'speaker_id': 'S2', 'text': 'International GMV grew 30% as cross-border tools like Shopify Markets gain adoption.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Colin Sebastian with Baird.'}, {'speaker_id': 'S5', 'text': 'Harley, how are merchants utilizing Shopify Magic and AI sidekick tools?'}, {'speaker_id': 'S1', 'text': 'Merchants using AI tools are saving hours each week on catalog generation and customer support.'}]}, 'RY': {'text': "Welcome to Royal Bank of Canada's third-quarter earnings conference call. Joining us today are Dave McKay, President and CEO, and Katherine Gibson, CFO. RBC reported solid third-quarter net income of 4.5 billion, with return on equity of 15.7 percent. Common Equity Tier 1 ratio was 13.0 percent, reflecting strong internal capital generation following the HSBC Canada acquisition. We are now ready for analyst questions. First question comes from Mario Mendonca with TD Securities. Dave, how is HSBC Canada integration progressing in terms of cost and revenue synergies? HSBC integration is ahead of schedule with client retention exceeding 95 percent. Our next question comes from Gabriel Dechaine with National Bank Financial. Katherine, what is your outlook on provisions for credit losses in commercial real estate? Our credit quality remains sound with prudent allowances reflecting conservative underwriting. Our next question comes from Meny Grauman with Scotiabank. Dave, how are personal and commercial deposit margins performing in the current rate environment? Deposit balances grew 8 percent, benefiting from our leading Canadian retail banking franchise.", 'utterances': [{'speaker_id': 'S0', 'text': "Welcome to Royal Bank of Canada's third-quarter earnings conference call. Joining us today are Dave McKay, President and CEO, and Katherine Gibson, CFO."}, {'speaker_id': 'S1', 'text': 'RBC reported solid third-quarter net income of $4.5 billion, with return on equity of 15.7%.'}, {'speaker_id': 'S2', 'text': 'Common Equity Tier 1 ratio was 13.0%, reflecting strong internal capital generation following the HSBC Canada acquisition.'}, {'speaker_id': 'S0', 'text': 'We are now ready for analyst questions. First question comes from Mario Mendonca with TD Securities.'}, {'speaker_id': 'S3', 'text': 'Dave, how is HSBC Canada integration progressing in terms of cost and revenue synergies?'}, {'speaker_id': 'S1', 'text': 'HSBC integration is ahead of schedule with client retention exceeding 95%.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Gabriel Dechaine with National Bank Financial.'}, {'speaker_id': 'S4', 'text': 'Katherine, what is your outlook on provisions for credit losses in commercial real estate?'}, {'speaker_id': 'S2', 'text': 'Our credit quality remains sound with prudent allowances reflecting conservative underwriting.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Meny Grauman with Scotiabank.'}, {'speaker_id': 'S5', 'text': 'Dave, how are personal and commercial deposit margins performing in the current rate environment?'}, {'speaker_id': 'S1', 'text': 'Deposit balances grew 8%, benefiting from our leading Canadian retail banking franchise.'}]}, 'CNR': {'text': "Welcome to Canadian National Railway's quarterly conference call. I will turn the meeting over to Tracy Robinson, President and CEO, and Ghislain Houle, CFO. CN delivered second-quarter operating revenues of 4.33 billion with an operating ratio of 62.0 percent. Adjusted diluted EPS was 1.84, with free cash flow of 1.15 billion generated year-to-date. We will now begin the question-and-answer session. Our first question comes from Fadi Chamoun with BMO Capital Markets. Tracy, what is your outlook for Canadian grain carloads and intermodal volume growth? Grain shipments are expected to be strong, supported by high operating velocity and train lengths. Our next question comes from Konark Gupta with Scotiabank. Ghislain, how are fuel productivity and labor cost containment tracking against guidance? Fuel efficiency improved 2 percent, helping mitigate inflationary cost pressures across the network. Our next question comes from Walter Spracklin with RBC Capital Markets. Tracy, can you speak to customer supply chain partnerships at the Port of Prince Rupert? Our corridor collaboration has restored competitive dwell times and attracted new vessel services.", 'utterances': [{'speaker_id': 'S0', 'text': "Welcome to Canadian National Railway's quarterly conference call. I will turn the meeting over to Tracy Robinson, President and CEO, and Ghislain Houle, CFO."}, {'speaker_id': 'S1', 'text': 'CN delivered second-quarter operating revenues of $4.33 billion with an operating ratio of 62.0%.'}, {'speaker_id': 'S2', 'text': 'Adjusted diluted EPS was $1.84, with free cash flow of $1.15 billion generated year-to-date.'}, {'speaker_id': 'S0', 'text': 'We will now begin the question-and-answer session. Our first question comes from Fadi Chamoun with BMO Capital Markets.'}, {'speaker_id': 'S3', 'text': 'Tracy, what is your outlook for Canadian grain carloads and intermodal volume growth?'}, {'speaker_id': 'S1', 'text': 'Grain shipments are expected to be strong, supported by high operating velocity and train lengths.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Konark Gupta with Scotiabank.'}, {'speaker_id': 'S4', 'text': 'Ghislain, how are fuel productivity and labor cost containment tracking against guidance?'}, {'speaker_id': 'S2', 'text': 'Fuel efficiency improved 2%, helping mitigate inflationary cost pressures across the network.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Walter Spracklin with RBC Capital Markets.'}, {'speaker_id': 'S5', 'text': 'Tracy, can you speak to customer supply chain partnerships at the Port of Prince Rupert?'}, {'speaker_id': 'S1', 'text': 'Our corridor collaboration has restored competitive dwell times and attracted new vessel services.'}]}, 'ENB': {'text': "Welcome to Enbridge's quarterly earnings conference call. Speaking today are Greg Ebel, President and CEO, and Patrick Murray, CFO. Enbridge delivered solid results with adjusted EBITDA of 4.3 billion, supported by record Mainline throughput. Distributable cash flow was 2.8 billion, keeping us fully on track to achieve our full-year financial guidance. We will now take questions. Our first question comes from Robert Kwan with RBC Capital Markets. Greg, could you comment on gas utility acquisitions integration and organic expansion capital? The gas distribution acquisitions are performing exceptionally well, providing stable regulated cash flows. Our next question comes from Linda Ezergailis with TD Cowen. Patrick, how is debt leverage progressing toward your target range of 4.5 to 5.0 times? Our balance sheet remains in great shape, supported by predictable utility cash flows. Our next question comes from Robert Catellier with CIBC World Markets. Greg, what are the growth opportunities in offshore Gulf Coast crude export terminals? Our Ingleside terminal achieved record loadings, solidifying our competitive advantage in energy infrastructure.", 'utterances': [{'speaker_id': 'S0', 'text': "Welcome to Enbridge's quarterly earnings conference call. Speaking today are Greg Ebel, President and CEO, and Patrick Murray, CFO."}, {'speaker_id': 'S1', 'text': 'Enbridge delivered solid results with adjusted EBITDA of $4.3 billion, supported by record Mainline throughput.'}, {'speaker_id': 'S2', 'text': 'Distributable cash flow was $2.8 billion, keeping us fully on track to achieve our full-year financial guidance.'}, {'speaker_id': 'S0', 'text': 'We will now take questions. Our first question comes from Robert Kwan with RBC Capital Markets.'}, {'speaker_id': 'S3', 'text': 'Greg, could you comment on gas utility acquisitions integration and organic expansion capital?'}, {'speaker_id': 'S1', 'text': 'The gas distribution acquisitions are performing exceptionally well, providing stable regulated cash flows.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Linda Ezergailis with TD Cowen.'}, {'speaker_id': 'S4', 'text': 'Patrick, how is debt leverage progressing toward your target range of 4.5 to 5.0 times?'}, {'speaker_id': 'S2', 'text': 'Our balance sheet remains in great shape, supported by predictable utility cash flows.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Robert Catellier with CIBC World Markets.'}, {'speaker_id': 'S5', 'text': 'Greg, what are the growth opportunities in offshore Gulf Coast crude export terminals?'}, {'speaker_id': 'S1', 'text': 'Our Ingleside terminal achieved record loadings, solidifying our competitive advantage in energy infrastructure.'}]}, 'ATD': {'text': 'Welcome to the Alimentation Couche-Tard quarterly conference call. I will turn the floor over to Alex Miller, President and CEO, and Filipe Da Silva, Chief Financial Officer. Our total merchandise and service revenues reached 4.1 billion. Cash flow from operations reached 450 million, supporting our dividend distribution. Adjusted net earnings were 725 million, with return on capital employed maintaining a strong 15.2 percent. We are now ready for analyst questions. First question comes from Mark Petrie with CIBC World Markets. Alex, can you give an update on same-store merchandise sales and fresh food category growth? Fresh food initiatives expanded nicely with fresh bakery and beverage driving customer basket sizes. Our next question comes from Irene Nattel with RBC Capital Markets. Filipe, how are fuel gross margins behaving across US and European retail networks? Fuel margins remained resilient, reflecting disciplined pricing and localized supply optimization. Our next question comes from Vishal Shreedhar with National Bank Financial. Alex, what is the strategy regarding European convenience store network expansion? We are successfully rebranding acquired retail stations while introducing our Circle K loyalty program.', 'utterances': [{'speaker_id': 'S0', 'text': 'Welcome to the Alimentation Couche-Tard quarterly conference call. I will turn the floor over to Alex Miller, President and CEO, and Filipe Da Silva, Chief Financial Officer.'}, {'speaker_id': 'S1', 'text': 'Our total merchandise and service revenues reached $4.1 billion. Cash flow from operations reached $450 million, supporting our dividend distribution.'}, {'speaker_id': 'S2', 'text': 'Adjusted net earnings were $725 million, with return on capital employed maintaining a strong 15.2%.'}, {'speaker_id': 'S0', 'text': 'We are now ready for analyst questions. First question comes from Mark Petrie with CIBC World Markets.'}, {'speaker_id': 'S3', 'text': 'Alex, can you give an update on same-store merchandise sales and fresh food category growth?'}, {'speaker_id': 'S1', 'text': 'Fresh food initiatives expanded nicely with fresh bakery and beverage driving customer basket sizes.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Irene Nattel with RBC Capital Markets.'}, {'speaker_id': 'S4', 'text': 'Filipe, how are fuel gross margins behaving across US and European retail networks?'}, {'speaker_id': 'S2', 'text': 'Fuel margins remained resilient, reflecting disciplined pricing and localized supply optimization.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Vishal Shreedhar with National Bank Financial.'}, {'speaker_id': 'S5', 'text': 'Alex, what is the strategy regarding European convenience store network expansion?'}, {'speaker_id': 'S1', 'text': 'We are successfully rebranding acquired retail stations while introducing our Circle K loyalty program.'}]}, 'MRU': {'text': "Welcome to Metro Inc.'s third-quarter earnings conference call. I will turn the meeting over to Eric La Fleche, President and CEO, and Francois Thibault, CFO. In our third quarter, sales reached 6.65 billion, an increase of 3.5 percent. Operating income before depreciation and amortization reached 615 million, reflecting stable retail operating margins. We are now ready for analyst questions. First question comes from Mark Petrie with CIBC World Markets. Eric, can you speak to food basket inflation and pharmacy retail performance? Our discount banner network drove positive tonnage growth while pharmacy prescription sales grew 6 percent. Our next question comes from Michael Van Aelst with TD Securities. Francois, how is automated distribution center ramp-up impacting gross margin and supply chain efficiency? The automated distribution centers in Terrebonne and Toronto are delivering expected productivity gains. Our next question comes from Chris Li with Desjardins. Eric, how is the Moi Rewards loyalty program contributing to customer retention? Moi Rewards enrollment exceeded 2.5 million active members, generating higher personalized promotion engagement.", 'utterances': [{'speaker_id': 'S0', 'text': "Welcome to Metro Inc.'s third-quarter earnings conference call. I will turn the meeting over to Eric La Fleche, President and CEO, and Francois Thibault, CFO."}, {'speaker_id': 'S1', 'text': 'In our third quarter, sales reached $6.65 billion, an increase of 3.5%.'}, {'speaker_id': 'S2', 'text': 'Operating income before depreciation and amortization reached $615 million, reflecting stable retail operating margins.'}, {'speaker_id': 'S0', 'text': 'We are now ready for analyst questions. First question comes from Mark Petrie with CIBC World Markets.'}, {'speaker_id': 'S3', 'text': 'Eric, can you speak to food basket inflation and pharmacy retail performance?'}, {'speaker_id': 'S1', 'text': 'Our discount banner network drove positive tonnage growth while pharmacy prescription sales grew 6%.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Michael Van Aelst with TD Securities.'}, {'speaker_id': 'S4', 'text': 'Francois, how is automated distribution center ramp-up impacting gross margin and supply chain efficiency?'}, {'speaker_id': 'S2', 'text': 'The automated distribution centers in Terrebonne and Toronto are delivering expected productivity gains.'}, {'speaker_id': 'S0', 'text': 'Our next question comes from Chris Li with Desjardins.'}, {'speaker_id': 'S5', 'text': 'Eric, how is the Moi Rewards loyalty program contributing to customer retention?'}, {'speaker_id': 'S1', 'text': 'Moi Rewards enrollment exceeded 2.5 million active members, generating higher personalized promotion engagement.'}]}}

